	struct iio_buffer *buffer = indio_dev->buffer;
	struct ad5686_state *st = iio_priv(indio_dev);
	u16 val[AD5686_MAX_CHANNELS] = { };
	int ret;

	ret = iio_pop_from_buffer(buffer, val);
	if (ret) {
